pub(super) fn flood_tet_component(
    seed: usize,
    tets: &[[usize; 4]],
    face_map: &HashMap<[usize; 3], Vec<usize>>,
    protected_faces: &HashSet<[usize; 3]>,
    outside: &[bool],
) -> Vec<usize> {
    let mut seen = HashSet::from([seed]);
    let mut component = Vec::new();
    let mut queue = VecDeque::from([seed]);
    while let Some(tet_idx) = queue.pop_front() {
        component.push(tet_idx);
        for face in tet_faces(tets[tet_idx]) {
            if protected_faces.contains(&face) {
                continue;
            }
            let Some(owners) = face_map.get(&face) else {
                continue;
            };
            for &neighbor in owners {
                if outside[neighbor] || !seen.insert(neighbor) {
                    continue;
                }
                queue.push_back(neighbor);
            }
        }
    }
    component
}

pub(super) fn tet_centroid(points: &[Point], tet: [usize; 4]) -> Point {
    let [a, b, c, d] = tet;
    Point::new_3d(
        0.25 * (points[a].x + points[b].x + points[c].x + points[d].x),
        0.25 * (points[a].y + points[b].y + points[c].y + points[d].y),
        0.25 * (points[a].z + points[b].z + points[c].z + points[d].z),
    )
}

pub(super) fn boundary_faces(tets: impl IntoIterator<Item = [usize; 4]>) -> HashSet<[usize; 3]> {
    let mut counts: HashMap<[usize; 3], usize> = HashMap::new();
    for tet in tets {
        for face in tet_faces(tet) {
            *counts.entry(face).or_insert(0) += 1;
        }
    }
    counts
        .into_iter()
        .filter_map(|(face, count)| (count == 1).then_some(face))
        .collect()
}

/// Build a bounded local Delaunay proposal for one side of a blocked facet.
/// The proposal is deliberately only a candidate: callers must retain the
/// exact cavity-boundary and protected-constraint checks before committing it.
pub(super) fn local_facet_side_delaunay_candidates(
    points: &mut Vec<Point>,
    tets: &[[usize; 4]],
    remove: &[usize],
    facet: [usize; 3],
    side: i8,
    boundary: &[[usize; 3]],
    max_points: usize,
) -> Option<Vec<[usize; 4]>> {
    let mut nodes = facet.to_vec();
    for face in boundary {
        for node in face {
            if !nodes.contains(node) {
                nodes.push(*node);
            }
        }
    }
    nodes.sort_unstable();

    // Centroids of the removed tets give the candidate generator interior
    // vertices on both re-entrant lobes.  They are added in removed-tet order
    // for deterministic output and never replace constrained boundary nodes.
    for anchor in cavity_side_anchors(points, tets, remove, facet, side) {
        if nodes.len() >= max_points {
            return None;
        }
        let node = points.len();
        points.push(anchor);
        nodes.push(node);
    }
    if nodes.len() < 4 || nodes.len() > max_points {
        return None;
    }

    let local_points: Vec<_> = nodes.iter().map(|&node| points[node]).collect();
    let (_, local_tets) = run_delaunay(&local_points);
    if local_tets.is_empty() {
        return None;
    }

    let mut surface = boundary.to_vec();
    surface.push(sorted3(facet));
    let mut accepted = Vec::new();
    for tet in local_tets {
        let candidate = [nodes[tet[0]], nodes[tet[1]], nodes[tet[2]], nodes[tet[3]]];
        if tet_samples_are_inside_closed_surface(points, candidate, &surface) {
            accepted.push(candidate);
        }
    }
    (!accepted.is_empty()).then_some(accepted)
}

/// Conservative local admission for a Delaunay candidate.  Sampling the tet
/// centroid, face centroids, and edge midpoints rules out a candidate that
/// crosses a re-entrant side boundary.  Exact boundary equality is checked by
/// the caller before the proposal can mutate the mesh.
pub(super) fn tet_samples_are_inside_closed_surface(
    points: &[Point],
    tet: [usize; 4],
    surface: &[[usize; 3]],
) -> bool {
    let vertices = tet.map(|node| points[node]);
    let mut samples = Vec::with_capacity(11);
    samples.push(tet_centroid(points, tet));
    for face in tet_faces(tet) {
        let [a, b, c] = face.map(|node| points[node]);
        samples.push(Point::new_3d(
            (a.x + b.x + c.x) / 3.0,
            (a.y + b.y + c.y) / 3.0,
            (a.z + b.z + c.z) / 3.0,
        ));
    }
    for (left, right) in [(0, 1), (0, 2), (0, 3), (1, 2), (1, 3), (2, 3)] {
        samples.push(Point::new_3d(
            (vertices[left].x + vertices[right].x) / 2.0,
            (vertices[left].y + vertices[right].y) / 2.0,
            (vertices[left].z + vertices[right].z) / 2.0,
        ));
    }
    samples
        .into_iter()
        .all(|sample| point_in_or_on_closed_surface(points, sample, surface))
}
